  "inlineSchema": "datasource db {\n  provider = \"postgresql\"\n  url      = env(\"DB_URL\")\n}\n\ngenerator client {\n  provider      = \"prisma-client-js\"\n  binaryTargets = [\"native\", \"linux-musl-openssl-3.0.x\"]\n  output        = \"../generated/prisma_client\"\n}\n\nenum Role {\n  USER\n  ADMIN\n  SUPERADMIN\n}\n\n// User model representing customers\nmodel User {\n  id            String     @id @default(cuid())\n  name          String?\n  email         String     @unique\n  emailVerified DateTime?\n  mobileNumber  String?\n  image         String?\n  password      String?\n  role          Role       @default(USER)\n  accounts      Account[]\n  address       Address?\n  refreshToken  String?\n  orders        Order[]\n  reviews       Review[]\n  createdAt     DateTime   @default(now())\n  updatedAt     DateTime   @updatedAt\n  cartItem      CartItem[]\n  emails        Email[]\n}\n\n// Account model for user's authentication accounts\nmodel Account {\n  provider          String\n  providerAccountId String\n  userId            String  @unique\n  type              String\n  refresh_token     String?\n  access_token      String?\n  expires_at        Int?\n  token_type        String?\n  scope             String?\n  id_token          String?\n  session_state     String?\n  user              User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@id([provider, providerAccountId])\n}\n\n// VerificationToken model\nmodel VerificationToken {\n  identifier String\n  token      String\n  expires    DateTime\n\n  @@id([identifier, token])\n}\n\n// Address model for user's shipping address\nmodel Address {\n  id             String  @id @default(cuid())\n  street         String\n  city           String\n  county         String\n  postalCode     String\n  pickupLocation String?\n  country        String  @default(\"Kenya\")\n  user           User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  userId         String  @unique\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// Category model\nmodel Category {\n  id          String    @id @default(cuid())\n  name        String\n  description String?\n  products    Product[]\n}\n\nmodel ProductTags {\n  productId String\n  tagId     String\n\n  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n  tag     Tag     @relation(fields: [tagId], references: [id], onDelete: Cascade)\n\n  @@id([productId, tagId])\n}\n\n// Tag model\nmodel Tag {\n  id          String        @id @default(cuid())\n  name        String\n  description String?\n  products    ProductTags[]\n}\n\n// Product model\nmodel Product {\n  id          String        @id @default(cuid())\n  name        String\n  description String\n  slug        String        @unique @default(\"\")\n  price       Int\n  stock       Int\n  images      String[] // URLs of product images\n  category    Category?     @relation(fields: [categoryId], references: [id], onDelete: Cascade)\n  categoryId  String?\n  tags        ProductTags[]\n  createdAt   DateTime      @default(now())\n  updatedAt   DateTime      @updatedAt\n  reviews     Review[]\n  orderItem   OrderItem[]\n  cartItem    CartItem[]\n\n  @@index([slug])\n}\n\nmodel CartItem {\n  userId    String\n  productId String\n  quantity  Int\n\n  user    User    @relation(fields: [userId], references: [id])\n  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@id([userId, productId])\n}\n\nenum OrderStatus {\n  SCHEDULED\n  FAILED\n  PARTIALLY_FULLFILLED\n  AWAITING_PAYMENT\n  BACK_ORDERED\n  ON_HOLD\n  REFUNDED\n  RETURNED\n  DELIVERED\n  SHIPPED\n  CANCELLED\n  COMPLETED\n  PROCESSING\n  PENDING\n}\n\n// Order model\nmodel Order {\n  id         String      @id @default(cuid())\n  createdAt  DateTime    @default(now())\n  status     OrderStatus @default(PENDING)\n  totalPrice Float\n  user       User        @relation(fields: [userId], references: [id])\n  userId     String\n  items      OrderItem[]\n  payment    Payment?\n  Email      Email[]\n}\n\n// OrderItem model representing items in an order\nmodel OrderItem {\n  id        String  @id @default(cuid())\n  quantity  Int\n  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n  productId String\n  order     Order   @relation(fields: [orderId], references: [id])\n  orderId   String\n}\n\nenum PaymentStatus {\n  PENDING\n  CHARGEBACK\n  VOIDED\n  CAPTURED\n  AUTHORIZED\n  PARTIALLY_REFUNDED\n  REFUNDED\n  FAILED\n  COMPLETED\n}\n\n// Payment model\nmodel Payment {\n  id                String        @id @default(cuid())\n  amount            Float\n  currency          String        @default(\"ksh\")\n  status            PaymentStatus @default(PENDING)\n  checkoutRequestId String?       @unique\n  failureReason     String?\n  orderId           String?       @unique\n  order             Order?        @relation(fields: [orderId], references: [id])\n  createdAt         DateTime      @default(now())\n  updatedAt         DateTime      @updatedAt\n}\n\n// Email model for tracking sent emails\nmodel Email {\n  id          String      @id @default(cuid())\n  to          String\n  subject     String\n  template    String? // Template name used (optional)\n  content     String\n  status      EmailStatus @default(PENDING)\n  retryCount  Int         @default(0)\n  error       String?\n  userId      String? // User who triggered the email\n  user        User?       @relation(fields: [userId], references: [id], onDelete: Cascade)\n  orderId     String? // reference to related order\n  order       Order?      @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  resendId    String?\n  scheduledAt DateTime? // for scheduled emails\n  sentAt      DateTime?\n  createdAt   DateTime    @default(now())\n  updatedAt   DateTime    @updatedAt\n\n  @@index([to])\n  @@index([status])\n  @@index([createdAt])\n  @@index([userId])\n  @@index([orderId])\n}\n\n// Email status enum\nenum EmailStatus {\n  PENDING\n  SENT\n  FAILED\n  RETRYING\n  BOUNCED\n  DELIVERED\n  OPENED\n  CLICKED\n}\n\n// Review model\nmodel Review {\n  id        String   @id @default(cuid())\n  rating    Int // Rating out of 5\n  comment   String?\n  user      User     @relation(fields: [userId], references: [id])\n  userId    String\n  product   Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n  productId String\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n",
